mapper.select:
select count(*) from dashboard_subscription
 where del_flag = '0' and upper(site_code) = upper(#{siteCode}) and lower(name) = lower(#{name})
 and id <> #{excludeId}

mapper.update:
update dashboard_subscription
   set last_run_at = #{runAt}, last_status = #{status}, last_error = #{error}
 , last_slot = #{lastSlot}
 where id = #{id}

mapper.select:
select id, subscription_id, site_code, trigger_type, period, receiver_type, receiver_id, receiver_name,
       status, error, message_id, operator, create_time
  from dashboard_subscription_log
 where subscription_id = #{subscriptionId}
 order by id desc
 limit #{limit}
